if(corpusInvalid)return[{json:{ingest_error:'CORPUS_JSON_INVALID',collect_error:'CORPUS_JSON_INVALID'}}];
const explicit=pasted!=null||arr(raw.documents)||arr(raw.schedule_knowledge_blocks);
